// WF-08 · Restauración del payload tras ejecutar la contención.
//
// El nodo HTTP Request SUSTITUYE el item por su propia respuesta (body,
// headers, statusCode). Sin restaurar aquí, 'Registrar en containment_log'
// recibe { body, headers, statusCode } en vez de la alerta, y $json.alert_id
// llega undefined. El síntoma no menciona el HTTP node: el Postgres falla con
// 'Query Parameters must be a string of comma-separated values or an array of
// values', un error genérico que no apunta a la causa real.
//
// mode=runOnceForEachItem: .item SÓLO resuelve el item emparejado en este
// modo. Estaba usando .item con el modo por defecto (runOnceForAllItems),
// donde no hay item actual que resolver — con dos acciones para la misma
// alerta (bloqueo de IP + aislamiento) el emparejamiento no era fiable.
//
// También resuelve el RULE_ID de Cloudflare: el id de la regla recién creada
// sólo se conoce aquí, en la respuesta real. Sin esto, el undo_payload
// persistido conservaría el placeholder literal y WF-07 jamás podría revertir.

// @blinksec-inject: lib/containment.js

const origen = $('Separar acciones').item.json;
const respuesta = $input.item.json;

const ruleId = respuesta.body?.result?.id ?? null;
const accion = resolveRuleId(origen.accion, ruleId);

return {
  json: {
    ...origen,
    accion,
    httpStatus: respuesta.statusCode ?? null,
  },
};

